Set-StrictMode -Version Latest

function New-AgentWorkspaceMutationDependencies([scriptblock]$TestFile,[scriptblock]$GetLength,[scriptblock]$ReadBytes,[scriptblock]$WriteBytes,[scriptblock]$DeleteFile,[scriptblock]$EnsureDirectory,[scriptblock]$MoveFile,[scriptblock]$ReplaceFile,[object]$PathDependencies=$null) {
    foreach($item in @(@('TestFile',$TestFile),@('GetLength',$GetLength),@('ReadBytes',$ReadBytes),@('WriteBytes',$WriteBytes),@('DeleteFile',$DeleteFile),@('EnsureDirectory',$EnsureDirectory),@('MoveFile',$MoveFile),@('ReplaceFile',$ReplaceFile))){if($item[1] -isnot [scriptblock]){throw "Workspace mutation adapter '$($item[0])' is required."}}
    return [pscustomobject]@{test_file=$TestFile;get_length=$GetLength;read_bytes=$ReadBytes;write_bytes=$WriteBytes;delete_file=$DeleteFile;ensure_directory=$EnsureDirectory;move_file=$MoveFile;replace_file=$ReplaceFile;path_dependencies=$PathDependencies}
}

function Test-AgentWorkspaceStoreFile([object]$Dependencies,[string]$Path) { if($null -eq $Dependencies -or $Dependencies.test_file -isnot [scriptblock]){throw 'Workspace file store is not configured.'};return [bool](& $Dependencies.test_file $Path) }
function Get-AgentWorkspaceStoreLength([object]$Dependencies,[string]$Path) { if($null -eq $Dependencies -or $Dependencies.get_length -isnot [scriptblock]){throw 'Workspace file store is not configured.'};$length=& $Dependencies.get_length $Path;if($length -isnot [int] -and $length -isnot [long] -and $length -isnot [short]){throw 'Workspace file store length must be an integer.'};if([long]$length -lt 0){throw 'Workspace file store length cannot be negative.'};return [long]$length }
function Read-AgentWorkspaceStoreBytes([object]$Dependencies,[string]$Path) { if($null -eq $Dependencies -or $Dependencies.read_bytes -isnot [scriptblock]){throw 'Workspace file store is not configured.'};$value=& $Dependencies.read_bytes $Path;if($value -isnot [byte[]]){throw 'Workspace file store reader must return one byte array.'};return ,$value }
function Write-AgentWorkspaceStoreBytes([object]$Dependencies,[string]$Path,[byte[]]$Bytes) { if($null -eq $Dependencies -or $Dependencies.write_bytes -isnot [scriptblock]){throw 'Workspace file store is not configured.'};& $Dependencies.write_bytes $Path $Bytes }
function Remove-AgentWorkspaceStoreFile([object]$Dependencies,[string]$Path) { if($null -eq $Dependencies -or $Dependencies.delete_file -isnot [scriptblock]){throw 'Workspace file store is not configured.'};& $Dependencies.delete_file $Path }
function Ensure-AgentWorkspaceStoreDirectory([object]$Dependencies,[string]$Path) { if($null -eq $Dependencies -or $Dependencies.ensure_directory -isnot [scriptblock]){throw 'Workspace file store is not configured.'};& $Dependencies.ensure_directory $Path }
function Move-AgentWorkspaceStoreFile([object]$Dependencies,[string]$Source,[string]$Destination,[switch]$Force) { if($null -eq $Dependencies -or $Dependencies.move_file -isnot [scriptblock]){throw 'Workspace file store is not configured.'};& $Dependencies.move_file $Source $Destination ([bool]$Force) }
function Replace-AgentWorkspaceStoreFile([object]$Dependencies,[string]$Source,[string]$Destination,[string]$Backup) { if($null -eq $Dependencies -or $Dependencies.replace_file -isnot [scriptblock]){throw 'Workspace file store is not configured.'};& $Dependencies.replace_file $Source $Destination $Backup }

